def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if not alive:
        base = 18.0 if hp > 3 else 45.0
        return float(max(0.0, min(budget, base)))

    threat_bids = []
    urgent_threat = 0.0
    cindy_bid = None
    david_bid = None

    for opp in alive:
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid')
        if bid is None:
            est = min(opp.get('budget', 0.0), opp.get('daily_salary', DAILY_SALARY) * 0.75)
            threat_bids.append(est)
            if opp.get('no_water_days', 0) >= 1 or opp.get('hp', 10) <= 3:
                urgent_threat = max(urgent_threat, est)
            continue

        name_hint = ''
        if bid is not None:
            threat_bids.append(float(bid))
        if opp.get('daily_salary') == 70 and opp.get('water_requirement') == 13:
            pass
        if bid is not None and bid > 120:
            cindy_bid = float(bid)
        elif bid is not None and 60 <= bid <= 120:
            david_bid = float(bid)
        if opp.get('no_water_days', 0) >= 1 or opp.get('hp', 10) <= 3:
            urgent_threat = max(urgent_threat, float(bid))

    highest_prev = max(threat_bids) if threat_bids else 0.0
    mid_prev = david_bid if david_bid is not None else highest_prev

    contested_units = float(supply) / float(WATER_REQ)

    if hp <= 2 or no_water_days >= 2:
        bid = max(highest_prev + 2.0, DAILY_SALARY * 1.15)
    elif hp <= 4 or no_water_days >= 1:
        bid = max(mid_prev + 2.0, urgent_threat + 2.0, DAILY_SALARY * 0.92)
    else:
        if contested_units >= 1.8:
            if david_bid is not None:
                bid = max(22.0, min(david_bid + 2.0, DAILY_SALARY * 0.95))
            else:
                bid = max(24.0, min(highest_prev * 0.7 + 3.0, DAILY_SALARY * 0.9))
        elif contested_units >= 1.45:
            bid = max(mid_prev + 3.0, DAILY_SALARY * 0.82)
        else:
            if hp >= 6 and no_water_days == 0:
                bid = min(DAILY_SALARY * 0.38, max(12.0, mid_prev * 0.45))
            else:
                bid = max(mid_prev + 4.0, DAILY_SALARY * 0.9)

    if day >= 8:
        bid = max(bid, DAILY_SALARY * 0.88)
    if hp <= 3:
        bid = max(bid, DAILY_SALARY * 1.0)

    bid = min(float(budget), float(bid))
    if bid < 0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    my_hp = int(my_status['hp'])
    my_budget = float(my_status['budget'])
    my_no_water_days = int(my_status['no_water_days'])

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append((opp_id, opp))

    if not alive_opps:
        return float(min(my_budget, DAILY_SALARY * 0.4))

    # Extract yesterday bids from previous_trace for immediate reaction
    yesterday_bids = []
    for _, opp in alive_opps:
        prev = opp.get('previous_trace', {})
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0

    # Pressure estimate: low supply increases competition; my hp/no-water increases urgency
    supply_factor = 0.0
    if supply <= MIN_SUPPLY:
        supply_factor = 1.0
    elif supply >= MAX_SUPPLY:
        supply_factor = 0.4
    else:
        # linear between 15 and 25
        supply_factor = 1.0 - (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY) * 0.6

    my_urgency = 0.0
    if my_hp <= 2:
        my_urgency = 1.0
    elif my_hp <= 4:
        my_urgency = 0.7
    elif my_hp <= 6:
        my_urgency = 0.4
    else:
        my_urgency = 0.25

    if my_no_water_days >= 2:
        my_urgency = max(my_urgency, 0.8)

    # If someone bid very high yesterday, they likely expect scarcity/pressure; match partially.
    opponent_pressure = 0.0
    if highest_prev_bid >= DAILY_SALARY * 1.6:  # ~144
        opponent_pressure = 1.0
    elif highest_prev_bid >= DAILY_SALARY * 0.9:  # ~81
        opponent_pressure = 0.6
    else:
        opponent_pressure = 0.25

    # Target bid: base tuned to medium scenario; avoid extreme overspending.
    base = DAILY_SALARY * (0.35 + 0.25 * supply_factor)
    bid = base + DAILY_SALARY * 0.25 * my_urgency + DAILY_SALARY * 0.15 * opponent_pressure

    # If my hp is critical, bid close to salary cap.
    if my_hp <= 2:
        bid = max(bid, DAILY_SALARY * 0.9)
    elif my_hp <= 4:
        bid = max(bid, DAILY_SALARY * 0.65)

    # If supply is high and my hp is safe, keep conservative.
    if supply >= 22.0 and my_hp >= 6:
        bid = min(bid, DAILY_SALARY * 0.5)

    # Ensure bid doesn't exceed budget; also keep a small floor to remain competitive.
    bid = float(min(my_budget, bid))
    bid = float(max(1.0, bid))
    return bid
